import{_ as i,c as n,o as s,a2 as t}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Politique de confidentialité","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/privacy.md","filePath":"fr/guide/privacy.md","lastUpdated":1793163976000}'),o={name:"fr/guide/privacy.md"};function a(r,e,l,c,u,d){return s(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="politique-de-confidentialite" tabindex="-1">Politique de confidentialité <a class="header-anchor" href="#politique-de-confidentialite" aria-label="Permalink to &quot;Politique de confidentialité&quot;">​</a></h1><p>NueZip est conçu comme une application entièrement hors ligne d&#39;abord. Votre confidentialité est notre priorité.</p><h2 id="conception-locale-uniquement" tabindex="-1">Conception locale uniquement <a class="header-anchor" href="#conception-locale-uniquement" aria-label="Permalink to &quot;Conception locale uniquement&quot;">​</a></h2><ul><li>Toutes les opérations d&#39;archives — compression, extraction, conversion, chiffrement — s&#39;exécutent entièrement sur votre Mac.</li><li>NueZip ne téléverse pas vos fichiers ou données vers des serveurs externes.</li><li>Aucun compte ou inscription n&#39;est requis pour utiliser l&#39;application.</li><li>Aucune connexion internet n&#39;est requise pour le fonctionnement normal.</li></ul><h2 id="ce-que-nous-ne-collectons-pas" tabindex="-1">Ce que nous ne collectons pas <a class="header-anchor" href="#ce-que-nous-ne-collectons-pas" aria-label="Permalink to &quot;Ce que nous ne collectons pas&quot;">​</a></h2><ul><li>Nous ne collectons pas vos fichiers, documents ou contenus d&#39;archive.</li><li>Nous ne suivons pas votre activité, votre comportement de navigation ou vos habitudes d&#39;utilisation.</li><li>Nous n&#39;envoyons aucune métadonnée de fichier ou information personnelle vers des serveurs externes.</li><li>Nous n&#39;incluons aucune analyse tierce, publicité ou SDK de suivi.</li><li>Nous n&#39;avons aucun système de télémétrie.</li></ul><h2 id="quelles-donnees-sont-stockees-localement" tabindex="-1">Quelles données sont stockées localement <a class="header-anchor" href="#quelles-donnees-sont-stockees-localement" aria-label="Permalink to &quot;Quelles données sont stockées localement&quot;">​</a></h2><p>Les données suivantes sont stockées uniquement sur votre appareil :</p><ul><li><strong>Réglages de l&#39;application</strong> : Thème, préférence de langue, préférences de compression</li><li><strong>Clé de licence</strong> : Si achetée (stockée en toute sécurité dans le trousseau local)</li><li><strong>Liste des fichiers récents</strong> : Archives récemment ouvertes pour un accès rapide</li><li><strong>Enregistrements de mots de passe</strong> : Stockés dans votre trousseau local si vous choisissez de les enregistrer</li><li><strong>Journaux</strong> : Journaux de débogage pour le dépannage (peuvent être supprimés à tout moment)</li></ul><h2 id="permissions-utilisees-par-l-application" tabindex="-1">Permissions utilisées par l&#39;application <a class="header-anchor" href="#permissions-utilisees-par-l-application" aria-label="Permalink to &quot;Permissions utilisées par l&#39;application&quot;">​</a></h2><ul><li><strong>Fichiers et dossiers</strong> : Requis pour lire les fichiers d&#39;archive et extraire les contenus.</li><li><strong>Extension Finder</strong> : Optionnelle, ajoute des éléments de menu contextuel au clic droit dans Finder.</li><li><strong>Notifications</strong> : Optionnelles, pour les alertes de fin sur les tâches de longue durée.</li></ul><p>Vous pouvez gérer ces permissions dans <strong>Réglages système → Confidentialité et sécurité</strong> à tout moment.</p><h2 id="achats-integres-licence" tabindex="-1">Achats intégrés / Licence <a class="header-anchor" href="#achats-integres-licence" aria-label="Permalink to &quot;Achats intégrés / Licence&quot;">​</a></h2><p>Les achats de licence sont traités par Apple via le Mac App Store. NueZip ne reçoit ni ne stocke vos informations de paiement. Les reçus de licence sont stockés localement pour vérifier la propriété.</p><h2 id="services-tiers" tabindex="-1">Services tiers <a class="header-anchor" href="#services-tiers" aria-label="Permalink to &quot;Services tiers&quot;">​</a></h2><p>NueZip n&#39;inclut aucune analyse tierce, publicité ou service de suivi. L&#39;application est entièrement autonome.</p><h2 id="demandes-de-confidentialite" tabindex="-1">Demandes de confidentialité <a class="header-anchor" href="#demandes-de-confidentialite" aria-label="Permalink to &quot;Demandes de confidentialité&quot;">​</a></h2><p>Puisque NueZip stocke toutes les données localement sur votre appareil, nous ne détenons aucune donnée personnelle sur nos serveurs. Si vous avez des questions sur la confidentialité, veuillez nous contacter.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Pour les questions de confidentialité, ouvrez un problème sur <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> ou envoyez-nous un e-mail.</p>',20)])])}const h=i(o,[["render",a]]);export{m as __pageData,h as default};
